public struct ManicatTokens {
    public let background, surface, surfaceRaised, surfaceMuted, foreground, textSecondary, textMuted: Color
    public let border, borderSubtle, borderStrong: Color
    public let accent, accentStrong, accentSubtle, accentForeground: Color
    public let success, warning, danger: Color
    public let controlOn, controlGlyph, controlFill, controlTrack, controlThumb, controlThumbOn: Color
    /// Four distinguishable colours for chart series, the counterpart of --series-1 to --series-4.
    public let series: [Color]

    public static let light = ManicatTokens(
        background: Color(hex: "#ffffff"), surface: Color(hex: "#ffffff"), surfaceRaised: Color(hex: "#ffffff"), surfaceMuted: Color(hex: "#f8f8f8"),
        foreground: Color(hex: "#0b0b0b"), textSecondary: Color(hex: "#585858"), textMuted: Color(hex: "#7d7d7d"),
        border: Color(hex: "#e9e9e9"), borderSubtle: Color(hex: "#f3f3f3"), borderStrong: Color(hex: "#c4c4c4"),
        accent: Color(hex: "#353535"), accentStrong: Color(hex: "#1f1f1f"), accentSubtle: Color(hex: "#353535", opacity: 0.1), accentForeground: Color(hex: "#ffffff"),
        success: Color(hex: "#007b12"), warning: Color(hex: "#b66400"), danger: Color(hex: "#cd1526"),
        controlOn: Color(hex: "#1d1d1d"), controlGlyph: Color(hex: "#ffffff"), controlFill: Color(hex: "#1d1d1d"), controlTrack: Color(hex: "#dcdcdc"), controlThumb: Color(hex: "#ffffff"), controlThumbOn: Color(hex: "#ffffff"),
        series: [Color(hex: "#1f7dcf"), Color(hex: "#7128a5"), Color(hex: "#e58f00"), Color(hex: "#009e84")]
    )

    public static let dark = ManicatTokens(
        background: Color(hex: "#141414"), surface: Color(hex: "#191919"), surfaceRaised: Color(hex: "#1f1f1f"), surfaceMuted: Color(hex: "#242424"),
        foreground: Color(hex: "#f2f2f2"), textSecondary: Color(hex: "#b4b4b4"), textMuted: Color(hex: "#8c8c8c"),
        border: Color(hex: "#2b2b2b"), borderSubtle: Color(hex: "#222222"), borderStrong: Color(hex: "#484848"),
        accent: Color(hex: "#bebebe"), accentStrong: Color(hex: "#e1e1e1"), accentSubtle: Color(hex: "#bebebe", opacity: 0.13), accentForeground: Color(hex: "#141414"),
        success: Color(hex: "#4cd676"), warning: Color(hex: "#ffb90e"), danger: Color(hex: "#ff736d"),
        controlOn: Color(hex: "#e8e8e8"), controlGlyph: Color(hex: "#141414"), controlFill: Color(hex: "#868686"), controlTrack: Color(hex: "#353535"), controlThumb: Color(hex: "#f5f5f5"), controlThumbOn: Color(hex: "#141414"),
        series: [Color(hex: "#55adff"), Color(hex: "#9c37be"), Color(hex: "#e66e00"), Color(hex: "#00a861")]
    )
}

